/**
 * Assert the browser cell-hash implementation matches the backend's.
 *
 * Phase 9.10.4 requires both languages to share golden fixtures. The expected
 * digests in `cell-hash.fixtures.ts` are generated by the Python implementation
 * (`python -m scripts.data_analysis_agent.runtime.patches.fixtures`); this
 * script compiles the real TypeScript and checks it reproduces them.
 *
 * Run with:  npm run verify:cell-hash
 *
 * If this fails, do not "fix" the fixtures. A divergence means a patch compiled
 * against the backend's view of a sheet would be applied against a different
 * view in the browser, which is the corruption the guards exist to prevent.
 */

import { execFileSync } from "node:child_process";
import { mkdtempSync, readdirSync, readFileSync, writeFileSync, cpSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

const SOURCE_DIR = "lib/data-analysis/patch";
const ENTRY = `
import { CELL_HASH_FIXTURES, RANGE_HASH_FIXTURES } from "./cell-hash.fixtures";
import { cellHash, rangeHash } from "./cell-hash";

export async function check() {
  const failures = [];
  for (const fixture of CELL_HASH_FIXTURES) {
    const actual = await cellHash(fixture.cell);
    if (actual !== fixture.expected) {
      failures.push({ kind: "cell", name: fixture.name, expected: fixture.expected, actual });
    }
  }
  for (const fixture of RANGE_HASH_FIXTURES) {
    const actual = await rangeHash(fixture.rangeA1, fixture.cells);
    if (actual !== fixture.expected) {
      failures.push({ kind: "range", name: fixture.name, expected: fixture.expected, actual });
    }
  }
  return { failures, total: CELL_HASH_FIXTURES.length + RANGE_HASH_FIXTURES.length };
}
`;

const workspace = mkdtempSync(join(tmpdir(), "cell-hash-"));
cpSync(join(SOURCE_DIR, "cell-hash.ts"), join(workspace, "cell-hash.ts"));
cpSync(join(SOURCE_DIR, "cell-hash.fixtures.ts"), join(workspace, "cell-hash.fixtures.ts"));
writeFileSync(join(workspace, "entry.ts"), ENTRY, "utf8");

execFileSync(
  "./node_modules/.bin/tsc",
  [
    "--target", "es2022",
    "--module", "es2022",
    "--moduleResolution", "bundler",
    "--lib", "es2022,dom",
    "--outDir", join(workspace, "out"),
    join(workspace, "cell-hash.ts"),
    join(workspace, "cell-hash.fixtures.ts"),
    join(workspace, "entry.ts"),
  ],
  { stdio: "inherit" },
);

// Rewrite to .mjs so plain node treats the output as ES modules.
const outDir = join(workspace, "out");
for (const name of readdirSync(outDir).filter((file) => file.endsWith(".js"))) {
  const source = readFileSync(join(outDir, name), "utf8").replace(
    /from "\.\/([\w.-]+)"/g,
    'from "./$1.mjs"',
  );
  writeFileSync(join(outDir, name.replace(/\.js$/, ".mjs")), source, "utf8");
}

const { check } = await import(pathToFileURL(join(outDir, "entry.mjs")).href);
const { failures, total } = await check();

for (const failure of failures) {
  console.error(
    `MISMATCH ${failure.kind} "${failure.name}"\n  backend: ${failure.expected}\n  browser: ${failure.actual}`,
  );
}

if (failures.length > 0) {
  console.error(`\n${failures.length} of ${total} cell-hash fixtures disagree with the backend.`);
  process.exit(1);
}

console.log(`All ${total} cell-hash fixtures match the backend implementation.`);
